	// ---- functions
	double f2u(double x) {
		if(x > 0.0) {
			if(x >= 4294967295.0) return 4294967295.0;
			return std::trunc(x);
		}
		return 0.0;
		return 0.0;
	}

	double wrap32(double x) {
		return x - TWO32 * std::floor(x / TWO32);
		return 0.0;
	}

	double wrap16(double x) {
		return x - 65536.0 * std::floor((x + 32768.0) / 65536.0);
		return 0.0;
	}

	double sat16(double x) {
		if(x > 32767.0) return 32767.0;
		if(x < -32768.0) return -32768.0;
		return x;
		return 0.0;
	}

	double i16(double x) {
		return wrap16(std::trunc(x));
		return 0.0;
	}

	double ssat(double x) {
		return sat16(std::trunc(x));
		return 0.0;
	}

	double fr(double x) {
		double c = x * 536870913.0;
		return c - (c - x);
		return 0.0;
	}

	double f16(double x) {
		if(std::fabs(x) < 0.00006103515625) return std::floor(x * 16777216.0 + 0.5) / 16777216.0;
		double c = x * 4398046511105.0;
		return c - (c - x);
		return 0.0;
	}

	double clamp01(double x) {
		if(x < 0.0) return 0.0;
		if(x > 1.0) return 1.0;
		return x;
		return 0.0;
	}

	double egCurve(double val, double slope) {
		return(1.0 + slope) * val / (1.0 + slope * std::fabs(val));
		return 0.0;
	}

	double valueShaper(double val, double shape) {
		double k = fr(fr(2.0 * shape) / fr(1.000100016593933 - shape));
		return fr(fr(fr(1.0 + k) * val) / fr(1.0 + fr(k * std::fabs(val))));
		return 0.0;
	}

	double rng32(double k) {
		double s = wrap32(rngS[k] * 1664525.0 + 1013904223.0);
		rngS[k] = s;
		double hi = std::floor(s / 65536.0);
		double lo = s - hi * 65536.0;
		return lo * 65536.0 + hi;
		return 0.0;
	}

	double rng16(double k) {
		double r = rng32(k);
		double lo = r - 65536.0 * std::floor(r / 65536.0);
		if(lo >= 32768.0) return lo - 65536.0;
		return lo;
		return 0.0;
	}

	double mainOsc(double v) {
		if(v < 3.0) return 2.0 * v;
		if(v == 3.0) return 6.0;
		if(v == 4.0) return 8.0;
		return 11.0;
		return 0.0;
	}

	double tableIndex(double f) {
		double v = f2u(fr(f / 440.0));
		if(v < 1.0) return 4.0;
		double l = 0.0;
		for(double k = 0.0; k < 32.0; k++) {
			if(v < 2.0) break;
			v = std::floor(v / 2.0);
			l = l + 1.0;
		}
		return cbx::min(10.0, l + 5.0);
		return 0.0;
	}

	void oscSetFreq(double o) {
		double f = fr(oFreq[o] * oPitch[o]);
		double w = oWave[o];
		if(w == W_SINE || w == W_NOISE) {
			oInc[o] = f2u(fr(4096.0 * f / fsr) * 1048576.0);
		} else if(w <= W_PWM) {
			oInc[o] = f2u(fr(1024.0 * f / fsr) * 4194304.0);
			oTbl[o] = tableIndex(f);
		} else {
			oInc[o] = f2u(fr(1024.0 * f / fsr) * 131072.0);
		}
	}

	void oscRecalc(double o) {
		double cent = fr(1.0 + fr(fr(fr(oFine[o] / 127.0) - 0.5) * 0.05946314334869385));
		double n = oCoarse[o] + oBase[o] - 60.0;
		if(n > 127.0) n = 127.0;
		if(n < 0.0) n = 0.0;
		oFreq[o] = fr(NOTEF[n] * cent);
	}

	void oscBase(double o, double note) {
		oBase[o] = note;
		oscRecalc(o);
	}

	double sineAt(double index) {
		double itg = std::floor(index / 1048576.0);
		double a = SINE[itg];
		return a + std::floor((SINE[itg + 1.0] - a) * (index - itg * 1048576.0) / 1048576.0);
		return 0.0;
	}

	double wtAt(double base, double index) {
		double itg = std::floor(index / 4194304.0);
		double a = WT[base + itg];
		return a + std::floor((WT[base + itg + 1.0] - a) * (index - itg * 4194304.0) / 4194304.0);
		return 0.0;
	}

	void noiseBlock(double o, double dst, double gain) {
		double p = oPhase[o];
		double inc = oInc[o];
		for(double i = 0.0; i < N; i++) {
			p = p + inc;
			if(p >= TWO32) {
				p = p - TWO32;
				oOut[o] = rng16(o);
			}
			SCR[dst + i] = i16(fr(oOut[o] * gain));
		}
		oPhase[o] = p;
	}

	double pwmIndex(double index, double pw) {
		return f2u(fr(fr(index) + pw * 2147483648.0));
		return 0.0;
	}

	void oscBlock(double o, double dst, double gain, double pw) {
		double w = oWave[o];
		double p = oPhase[o];
		double inc = oInc[o];
		if(w == W_SINE) {
			for(double i = 0.0; i < N; i++) {
				SCR[dst + i] = i16(fr(sineAt(p) * gain));
				p = wrap32(p + inc);
			}
		} else if(w <= 3.0) {
			double base = (w - 1.0) * WTS + oTbl[o] * 1024.0;
			for(double i = 0.0; i < N; i++) {
				SCR[dst + i] = i16(fr(wtAt(base, p) * gain));
				p = wrap32(p + inc);
			}
		} else if(w == W_NOISE) {
			noiseBlock(o, dst, gain);
			return;
		} else if(w == W_PWM) {
			double base = WTS + oTbl[o] * 1024.0;
			double smp = 0.0;
			for(double i = 0.0; i < N; i++) {
				smp = sat16(wtAt(base, p) - wtAt(base, pwmIndex(p, pw)));
				SCR[dst + i] = i16(fr(smp * gain));
				p = wrap32(p + inc);
			}
			oOut[o] = smp;
		}
		
		oPhase[o] = p;
	}

	void oscFmBlock(double o, double modBuf, double dst, double gain, double pw) {
		double w = oWave[o];
		double p = oPhase[o];
		double inc = oInc[o];
		double fm = oFm[o];
		if(w == W_SINE) {
			for(double i = 0.0; i < N; i++) {
				double index = wrap32(p + wrap32(f2u(fr(SCR[modBuf + i] * fm)) * 131072.0));
				SCR[dst + i] = i16(fr(sineAt(index) * gain));
				p = wrap32(p + inc);
			}
		} else if(w <= 3.0) {
			double base = (w - 1.0) * WTS + oTbl[o] * 1024.0;
			double smp = 0.0;
			for(double i = 0.0; i < N; i++) {
				double index = wrap32(p + wrap32(f2u(fr(SCR[modBuf + i] * fm)) * 524288.0));
				smp = wtAt(base, index);
				SCR[dst + i] = i16(fr(smp * gain));
				p = wrap32(p + inc);
			}
			oOut[o] = smp;
		} else if(w == W_NOISE) {
			noiseBlock(o, dst, gain);
			return;
		} else if(w == W_PWM) {
			double base = WTS + oTbl[o] * 1024.0;
			double smp = 0.0;
			for(double i = 0.0; i < N; i++) {
				double index = wrap32(p + wrap32(f2u(fr(SCR[modBuf + i] * fm)) * 524288.0));
				smp = sat16(wtAt(base, index) - wtAt(base, pwmIndex(index, pw)));
				SCR[dst + i] = i16(fr(smp * gain));
				p = wrap32(p + inc);
			}
			oOut[o] = smp;
		}
		oPhase[o] = p;
	}

	void qaddBuf(double dst, double src) {
		for(double i = 0.0; i < N; i++) SCR[dst + i] = sat16(SCR[dst + i] + SCR[src + i]);
	}

	void transBlock(double v, double dst) {
		double w = trWave[v];
		double ph = trPhase[v];
		if(w <= 1.0 || ph >= 2311061504.0) {
			for(double i = 0.0; i < N; i++) SCR[dst + i] = 0.0;
			return;
		}
		double base = (w - 2.0) * TRL;
		double stp = trPitch[v] * 1048576.0 * kr;
		for(double i = 0.0; i < N; i++) {
			if(ph < 2311061504.0) {
				SCR[dst + i] = i16(fr(trVol[v] * (TR[base + std::floor(ph / 1048576.0)] * 256.0)));
				ph = f2u(fr(ph + stp));
			} else {
				SCR[dst + i] = 0.0;
			}
		}
		trPhase[v] = ph;
	}

	double snapCalc(double v, double tm) {
		double ret = 0.0;
		if(snap[v] > 0.0) {
			ret = fr(fr(snap[v] * snap[v]) * 24.0);
			snap[v] = fr(snap[v] - fr(0.20000000298023224 * tm * kr));
		}
		return ret;
		return 0.0;
	}

	double decayCalc(double v) {
		double val = peValue[v];
		if(val > 0.0) val = fr(val - peDecay[v] * kr);
		else val = 0.0;
		peValue[v] = val;
		double sl = peSlope[v];
		return fr(fr(fr(1.0 + sl) * val) / fr(1.0 + fr(sl * std::fabs(val))));
		return 0.0;
	}

	double aeCalc(double v) {
		double val = aeValue[v];
		double st = aeState[v];
		if(st == EG_STOPPED) return 0.0;
		if(st == EG_REPEAT) {
			if(val > 0.0) {
				val = val - aeAttack[v] * kr;
			} else {
				aeRepCnt[v] = aeRepCnt[v] - 1.0;
				if(aeRepCnt[v] < 0.0) aeRepCnt[v] = aeRepCnt[v] + 256.0;
				if(aeRepCnt[v] <= 0.0) aeState[v] = EG_D;
				val = 1.0;
			}
			aeValue[v] = val;
			return egCurve(val, aeSlope[v]);
		}
		if(st == EG_A) {
			val = val + aeAttack[v] * kr;
			if(val >= 1.0) {
				val = 1.0;
				aeState[v] = EG_D;
			}
			aeValue[v] = val;
			return egCurve(val, aeInv[v]);
		}
		if(st == EG_D) {
			if(val > 0.0) {
				val = val - aeDecay[v] * kr;
				aeValue[v] = val;
				return egCurve(val, aeSlope[v]);
			}
			aeValue[v] = 0.0;
		}
		return 0.0;
		return 0.0;
	}

	void aeTrigger(double v) {
		if(aeRepeat[v] == 0.0) {
			aeState[v] = EG_A;
		} else {
			aeState[v] = EG_REPEAT;
			aeValue[v] = 1.0;
		}
		aeRepCnt[v] = aeRepeat[v];
	}

	double egTime(double itg, double k) {
		double val = itg / 127.0;
		double ret = fr((1.0 - (1.0 + k) * val / (1.0 + k * std::fabs(val))) * 2.0);
		if(ret > 1.0) return 1.0;
		return ret;
		return 0.0;
	}

	double softClip(double x) {
		double h = fr(0.5 * x);
		double a = fr(h * h);
		double num = fr(fr(fr(a + 105.0) * a) + 945.0);
		double den = fr(fr(fr(fr(15.0 * a) + 420.0) * a) + 945.0);
		if(den > FLT_MAX_) {
			if(num > FLT_MAX_) scNan = 1.0;
			return 0.0;
		}
		return fr(x * fr(num / den));
		return 0.0;
	}

	double fastTanh(double x) {
		if(x < -1.9500000476837158) return -1.0;
		if(x > 1.9500000476837158) return 1.0;
		return fr(fr(4.150000095367432 * x) / fr(4.289999961853027 + fr(x * x)));
		return 0.0;
	}

	double fastTan(double x) {
		double x2 = fr(x * x);
		return fr(fr(fr(-15.0 * x) + fr(x * x2)) / fr(3.0 * fr(-5.0 + fr(2.0 * x2))));
		return 0.0;
	}

	void svfRecalc(double v) {
		svG[v] = fastTan(fr(3.141592653589793 * svF[v] * kr));
	}

	void svfBlock(double v, double dst) {
		double ft = fType[v];
		if(ft == F_OFF || ft < F_LP || ft > F_OFF) return;
		double drive = svDrive[v];
		if(ft == F_LP2) {
			
			double fl = fr(svF[v] * kr * 2.2100000381469727);
			double q0 = 1.0 - svQ[v];
			double q = fr(q0 * 1.4 + q0 / (1.0 - fl));
			double a = svA[v];
			double b = svB[v];
			for(double i = 0.0; i < N; i++) {
				double x = softClip(fr(fr(SCR[dst + i] / 32767.0) * drive));
				a = fr(a + fr(fl * fr(fr(x - a) + fr(q * fr(a - b)))));
				if(a > 1.0) a = 1.0;
				else if(a < -1.0) a = -1.0;
				b = fr(b + fr(fl * fr(a - b)));
				if(b > 1.0) b = 1.0;
				else if(b < -1.0) b = -1.0;
				SCR[dst + i] = ssat(fr(b * 32767.0));
			}
			svA[v] = a;
			svB[v] = b;
			return;
		}
		
		double g = svG[v];
		double R = svQ[v];
		if(svF[v] >= 0.44990000128746033) R = 1.0;
		double ff = fr(g * g);
		double s1 = svS1[v];
		double s2 = svS2[v];
		double g0 = fr(1.0 / fr(1.0 + fr(g * 2.0 * R)));
		double f1 = fr(ff * g0);
		double gg0 = fr(g * g0);
		double den = fr(f1 + 1.0);
		double blown = 0.0;
		scNan = 0.0;
		for(double i = 0.0; i < N; i++) {
			if(blown != 0.0) {
				
				
				SCR[dst + i] = 0.0;
				continue;
			}
			double x = softClip(fr(fr(SCR[dst + i] / 32767.0) * drive));
			double y1 = fr(fr(fr(fr(f1 * x) + s2) + fr(gg0 * s1)) / den);
			double xx = fr(x - y1);
			double cs1 = softClip(s1);
			double y0 = fr(fr(cs1 + fr(g * xx)) * g0);
			double ugb = fr(2.0 * R * y0);
			s1 = fr(cs1 + fr(2.0 * g * fr(xx - ugb)));
			s2 = fr(s2 + fr(2.0 * g * y0));
			double y = 0.0;
			if(ft == F_LP) y = fastTanh(y1);
			else if(ft == F_HP) y = fr(fr(x - ugb) - y1);
			else if(ft == F_BP) y = y0;
			else if(ft == F_UBP) y = ugb;
			else if(ft == F_NOTCH) y = fr(x - ugb);
			else y = fr(y1 - fr(fr(x - ugb) - y1));
			SCR[dst + i] = ssat(fr(y * 32767.0));
			if(scNan != 0.0) {
				blown = 1.0;
				SCR[dst + i] = 0.0;
			} else if(std::fabs(s1) > FLT_MAX_ || std::fabs(s2) > FLT_MAX_) {
				blown = 1.0;
			}
		}
		if(blown != 0.0) {
			s1 = 0.0;
			s2 = 0.0;
		}
		svS1[v] = s1;
		svS2[v] = s2;
	}

	void distBlock(double v, double dst) {
		double s = dShape[v];
		for(double i = 0.0; i < N; i++) SCR[dst + i] = shapeSample(SCR[dst + i], s);
	}

	double shapeSample(double smp, double s) {
		double x = fr(smp / 32767.0);
		x = fr(fr(fr(1.0 + s) * x) / fr(1.0 + fr(s * std::fabs(x))));
		return i16(fr(x * 32767.0));
		return 0.0;
	}

	void srReduce(double v, double dst) {
		double inc = fr(decRate[v] * decRate[6.0]);
		for(double i = 0.0; i < N; i++) {
			decCnt[v] = fr(decCnt[v] + inc);
			if(decCnt[v] >= 1.0) {
				decCnt[v] = fr(decCnt[v] - 1.0);
				decHold[v] = SCR[dst + i];
			}
			SCR[dst + i] = decHold[v];
		}
	}

	void mixAdd(double v, double src) {
		double r = routing[v];
		double pl = panL[v];
		double pr = panR[v];
		if(r == 6.0) {
			for(double i = 0.0; i < N; i++) {
				double x = SCR[src + i];
				FXB[2.0 * i] = sat16(FXB[2.0 * i] + i16(fr(x * pl)));
				FXB[2.0 * i + 1.0] = sat16(FXB[2.0 * i + 1.0] + i16(fr(x * pr)));
			}
		} else if(r == 0.0 || r == 1.0) {
			double c = 128.0;
			if(r == 1.0) c = 0.0;
			for(double i = 0.0; i < N; i++) {
				double x = SCR[src + i];
				OUTB[c + i] = sat16(OUTB[c + i] + i16(fr(x * pl)));
				OUTB[c + 64.0 + i] = sat16(OUTB[c + 64.0 + i] + i16(fr(x * pr)));
			}
		} else {
			double c = 0.0;
			if(r == 2.0) c = 128.0;
			else if(r == 3.0) c = 192.0;
			else if(r == 5.0) c = 64.0;
			for(double i = 0.0; i < N; i++) OUTB[c + i] = sat16(OUTB[c + i] + SCR[src + i]);
		}
	}

	double lfoInc(double freq, double syncMode) {
		double lsr = fsr / N;
		if(syncMode <= 0.0 || syncMode >= 12.0) return f2u(fr(freq / fr(lsr)) * TWO32);
		double tf = 0.0;
		if(curBpm > 0.0) tf = fr(fr(curBpm / 60.0) / 4.0);
		double sc = 1.0;
		if(syncMode == 1.0) sc = 0.25;
		else if(syncMode == 2.0) sc = 0.5;
		else if(syncMode == 3.0) sc = 1.0;
		else if(syncMode == 4.0) sc = 2.0;
		else if(syncMode == 5.0) sc = 3.0;
		else if(syncMode == 6.0) sc = 4.0;
		else if(syncMode == 7.0) sc = 6.0;
		else if(syncMode == 8.0) sc = 8.0;
		else if(syncMode == 9.0) sc = 12.0;
		else if(syncMode == 10.0) sc = 16.0;
		else sc = 32.0;
		return f2u(fr(fr(tf * sc) / fr(lsr)) * TWO32);
		return 0.0;
	}

	void lfoSetFreq(double l, double f) {
		double x = fr(0.0078125 + fr(f * 0.9921875));
		lFreq[l] = fr(fr(fr(x * x) * x) * 200.0);
		lInc[l] = lfoInc(lFreq[l], lSync[l]);
	}

	double lfoCalc(double l) {
		double old = lPhase[l];
		double ph = wrap32(old + f2u(fr(lInc[l])));
		lPhase[l] = ph;
		double w = lWave[l];
		if(w == 0.0) return fr(fr(SINE[std::floor(ph / 1048576.0)] / 32767.0) + 1.0) / 2.0;
		if(w == 1.0) return fr(1.0 - std::fabs(fr(fr(fr(ph) / TWO32) * 2.0 - 1.0)));
		if(w == 2.0) return fr(fr(ph) / TWO32);
		if(w == 3.0) return fr(fr(4294967295.0 - ph) / TWO32);
		if(w == 4.0) {
			if(ph > 2147483647.0) return 1.0;
			return 0.0;
		}
		if(w == 5.0) {
			if(old > ph) lRnd[l] = fr(fr(rng32(16.0 + l)) / TWO32);
			return lRnd[l];
		}
		if(w == 6.0) {
			double x = fr(fr(ph) / TWO32);
			return fr(fr(x * x) * x);
		}
		if(w == 7.0) {
			double y = fr(fr(4294967295.0 - ph) / TWO32);
			return fr(fr(y * y) * y);
		}
		return 0.0;
		return 0.0;
	}

	void lfoRetrigger(double voice) {
		for(double l = 0.0; l < 6.0; l++) {
			if(lRetrig[l] == voice + 1.0) lPhase[l] = lOffset[l];
		}
	}

	void modUpdate(double dest, double amount, double val) {
		if(HASPTR[dest] == 0.0) return;
		double nv = clamp01(fr(fr(P[dest] / 127.0) + fr(amount * fr(fr(val * 2.0) - 1.0))));
		applyLxrParam(dest, std::trunc(fr(nv * 127.0)), nv, 1.0);
	}

	void resetParam(double dest) {
		if(HASPTR[dest] == 0.0) return;
		applyLxrParam(dest, P[dest], fr(P[dest] / 127.0), 0.0);
	}

	void resetTargets() {
		for(double i = 0.0; i < 6.0; i++) resetParam(vmDest[i]);
		for(double i = 0.0; i < 6.0; i++) resetParam(lDest[i]);
	}

	void setVeloDest(double i, double target) {
		resetTargets();
		vmDest[i] = MT[target];
	}

	void setLfoDest(double i, double target) {
		resetTargets();
		lDest[i] = MT[target];
	}

	void veloMod(double v, double val) {
		vmLast[v] = val;
		modUpdate(vmDest[v], vmAmount[v], val);
	}

	double waveVal(double itg, double flt, double isMod, double n) {
		if(isMod == 0.0) return itg;
		return cbx::min(n - 1.0, std::trunc(n * flt));
		return 0.0;
	}

	void setLxrParam(double idx, double val) {
		P[idx] = val;
		applyLxrParam(idx, val, fr(val / 127.0), 0.0);
	}

	void applyLxrParam(double idx, double itg, double flt, double isMod) {
		if(idx < 8.0) {
			if(idx == 1.0) oWave[0.0] = waveVal(itg, flt, isMod, 6.0);
			else if(idx == 2.0) oWave[2.0] = waveVal(itg, flt, isMod, 6.0);
			else if(idx == 3.0) oWave[4.0] = waveVal(itg, flt, isMod, 6.0);
			else if(idx == 4.0) oWave[6.0] = waveVal(itg, flt, isMod, 6.0);
			else if(idx == 6.0) oWave[8.0] = waveVal(itg, flt, isMod, 6.0);
			else if(idx == 7.0) oWave[11.0] = waveVal(itg, flt, isMod, 6.0);
		} else if(idx < 20.0) {
			
			double o = mainOsc(std::floor((idx - 8.0) / 2.0));
			if(idx - 8.0 - 2.0 * std::floor((idx - 8.0) / 2.0) == 0.0) oCoarse[o] = itg;
			else oFine[o] = itg;
			oscRecalc(o);
		} else if(idx < 27.0) {
			double o = 1.0;
			if(idx == 21.0) o = 3.0;
			else if(idx == 22.0) o = 5.0;
			else if(idx == 23.0) o = 9.0;
			else if(idx == 24.0) o = 10.0;
			else if(idx == 25.0) o = 12.0;
			else if(idx == 26.0) o = 13.0;
			oWave[o] = waveVal(itg, flt, isMod, 6.0);
		} else if(idx < 37.0) {
			if(idx == 27.0) oFreq[7.0] = fr(flt * 22000.0);
			else if(idx == 28.0) snMix = flt;
			else if(idx == 29.0) {
				oCoarse[9.0] = itg;
				oscRecalc(9.0);
			} else if(idx == 30.0) {
				oCoarse[10.0] = itg;
				oscRecalc(10.0);
			} else if(idx == 31.0) fmA1[4.0] = flt;
			else if(idx == 32.0) fmA2[4.0] = flt;
			else if(idx == 33.0) {
				oCoarse[12.0] = itg;
				oscRecalc(12.0);
			} else if(idx == 34.0) {
				oCoarse[13.0] = itg;
				oscRecalc(13.0);
			} else if(idx == 35.0) fmA1[5.0] = flt;
			else if(idx == 36.0) fmA2[5.0] = flt;
		} else if(idx < 43.0) {
			
			double v = idx - 37.0;
			svF[v] = fr(valueShaper(flt, -0.8999999761581421) * 0.44999998807907104);
			svfRecalc(v);
		} else if(idx < 49.0) {
			double v = idx - 43.0;
			svQ[v] = fr(1.0 - flt);
			if(svQ[v] < 0.10000000149011612) svQ[v] = 0.019999999552965164;
		} else if(idx < 60.0) {
			double k = idx - 49.0;
			double v = std::floor(k / 2.0);
			if(k - 2.0 * v == 0.0) aeAttack[v] = egTime(itg, K_ATTACK);
			else aeDecay[v] = egTime(itg, K_DECAY);
		} else if(idx < 62.0) {
			if(idx == 60.0) hhDecClosed = egTime(itg, K_DECAY);
			else hhDecOpen = egTime(itg, K_DECAY);
		} else if(idx < 68.0) {
			double v = idx - 62.0;
			double a = ((itg / 127.0) - 0.5) * 1.999;
			aeSlope[v] = 2.0 * a / (1.0 - a);
			aeInv[v] = -2.0 * a / (1.0 + a);
		} else if(idx < 70.0) {
			aeRepeat[idx - 65.0] = itg;
		} else if(idx < 74.0) {
			
			double val = fr(itg / 127.0);
			double ret = fr(1.0 - fr(fr(fr(1.0 + K_PITCH) * val) / fr(1.0 + fr(K_PITCH * val)))) * 2.0;
			if(ret > 1.0) ret = 1.0;
			peDecay[idx - 70.0] = ret;
		} else if(idx < 78.0) {
			double val = fr(itg / 127.0);
			pAmt[idx - 74.0] = fr(fr(val * val) * 32.0);
		} else if(idx < 82.0) {
			
			
			double a = cbx::min(0.9999, fr(fr(itg / 127.0) - 0.5) * 2.0);
			peSlope[idx - 78.0] = fr(2.0 * a / fr(1.0 - a));
		} else if(idx < 88.0) {
			double k = idx - 82.0;
			double v = std::floor(k / 2.0);
			if(k - 2.0 * v == 0.0) {
				fmAmt[v] = flt;
			} else {
				oCoarse[2.0 * v + 1.0] = itg;
				oscRecalc(2.0 * v + 1.0);
			}
		} else if(idx < 94.0) {
			vol[idx - 88.0] = flt;
		} else if(idx < 102.0) {
			if(idx < 97.0) pan[idx - 94.0] = itg;
			else if(idx > 98.0) pan[idx - 96.0] = itg;
		} else if(idx < 108.0) {
			
			double s = fr(flt - 0.0078125);
			dShape[idx - 102.0] = fr(fr(2.0 * s) / fr(1.0 - s));
		} else if(idx < 115.0) {
			decRate[idx - 108.0] = valueShaper(flt, -0.699999988079071);
		} else if(idx < 121.0) {
			lfoSetFreq(idx - 115.0, flt);
		} else if(idx < 127.0) {
			lAmount[idx - 121.0] = flt;
		} else if(idx < 128.0) {
			
		} else if(idx < 134.0) {
			svDrive[idx - 128.0] = fr(0.4000000059604645 + fr(fr(flt * flt) * 6.0));
		} else if(idx < 137.0) {
			mixOscs[idx - 134.0] = 0.0;
			if(itg != 0.0) mixOscs[idx - 134.0] = 1.0;
		} else if(idx < 143.0) {
			volMod[idx - 137.0] = 0.0;
			if(itg != 0.0) volMod[idx - 137.0] = 1.0;
		} else if(idx < 149.0) {
			vmAmount[idx - 143.0] = flt;
		} else if(idx < 155.0) {
			
		} else if(idx < 161.0) {
			lWave[idx - 155.0] = waveVal(itg, flt, isMod, 8.0);
		} else if(idx < 173.0) {
			
		} else if(idx < 179.0) {
			if(isMod == 0.0) lRetrig[idx - 173.0] = itg;
			else lRetrig[idx - 173.0] = std::trunc(7.0 * flt);
		} else if(idx < 185.0) {
			double l = idx - 179.0;
			lSync[l] = itg;
			lInc[l] = lfoInc(lFreq[l], itg);
		} else if(idx < 191.0) {
			lOffset[idx - 185.0] = f2u(flt * TWO32);
		} else if(idx < 197.0) {
			double v = idx - 191.0;
			if(isMod == 0.0) {
				fType[v] = itg + 1.0;
			} else {
				double t = std::trunc(7.0 * flt + 1.0);
				if(t >= F_OFF) t = F_OFF - 1.0;
				fType[v] = t;
			}
		} else if(idx < 203.0) {
			trVol[idx - 197.0] = flt;
		} else if(idx < 209.0) {
			double w = itg;
			if(isMod != 0.0) w = cbx::min(11.0, std::trunc(12.0 * flt));
			if(w >= 14.0) w = 0.0;
			trWave[idx - 203.0] = w;
		} else if(idx < 215.0) {
			
			trPitch[idx - 209.0] = fr(1.0 + fr(fr(itg / 33.900001525878906) - 0.75));
		} else if(idx < 221.0) {
			routing[idx - 215.0] = itg;
		} else if(idx < 228.0) {
			
		} else if(idx < 234.0) {
			pwm[idx - 228.0] = flt;
		} else if(idx == 234.0) {
			fxType = itg;
			fxUpdate();
		} else if(idx == 235.0) {
			fxRouting = itg;
		} else if(idx == 236.0) {
			fxDryWet = fr(itg / 100.0);
		} else if(idx == 237.0) {
			dsType = itg;
		} else if(idx < 242.0) {
			fxP[idx - 238.0] = flt;
			fxUpdate();
		} else if(idx == 242.0) {
			compSetRatio(itg);
		} else if(idx == 243.0) {
			oWave[14.0] = itg;
		} else if(idx == 245.0) {
			dlType = itg;
		}
	}

	void bpmChanged() {
		for(double l = 0.0; l < 6.0; l++) lInc[l] = lfoInc(lFreq[l], lSync[l]);
	}

	void updatePan(double v) {
		panL[v] = fr(std::sqrt(fr((127.0 - pan[v]) / 127.0)));
		panR[v] = fr(std::sqrt(fr(pan[v] / 127.0)));
	}

	double startPhase(double o, double offset) {
		double w = oWave[o];
		if(w == W_SINE) return f2u(fr(1072693248.0 * offset));
		if(w >= 1.0 && w <= 3.0) return f2u(fr(1069547520.0 * offset));
		return 0.0;
		return 0.0;
	}

	void drumTrigger(double v, double vel, double note) {
		lfoRetrigger(v);
		veloMod(v, fr(vel / 127.0));
		double offset = 1.0;
		if(trWave[v] == 1.0) offset = fr(offset - trVol[v]);
		double o = 2.0 * v;
		double w = oWave[o];
		if(w == W_SINE) oPhase[o] = f2u(fr(1024.0 + fr(1072692224.0 * offset)));
		else if(w >= 1.0 && w <= 3.0) oPhase[o] = f2u(fr(1069547520.0 * offset));
		else oPhase[o] = 0.0;
		oPhase[o + 1.0] = startPhase(o + 1.0, 1.0);
		oscBase(o, note);
		oscBase(o + 1.0, note);
		peValue[v] = 1.0;
		aeTrigger(v);
		velo[v] = fr(vel / 127.0);
		trPhase[v] = 0.0;
		snap[v] = 1.0;
		svS1[v] = 0.0;
		svS2[v] = 0.0;
		svA[v] = 0.0;
		svB[v] = 0.0;
		updatePan(v);
	}

	void snareTrigger(double vel, double note) {
		lfoRetrigger(3.0);
		veloMod(3.0, fr(vel / 127.0));
		double offset = 1.0;
		if(trWave[3.0] == 1.0) offset = fr(offset - trVol[3.0]);
		oPhase[6.0] = startPhase(6.0, offset);
		peValue[3.0] = 1.0;
		aeTrigger(3.0);
		velo[3.0] = fr(vel / 127.0);
		oscBase(6.0, note);
		trPhase[3.0] = 0.0;
		snap[3.0] = 1.0;
		updatePan(3.0);
	}

	void metalTrigger(double v, double vel, double isOpen, double note) {
		lfoRetrigger(v);
		veloMod(v, fr(vel / 127.0));
		double offset = 1.0;
		if(trWave[v] == 1.0) offset = fr(offset - trVol[v]);
		double o = mainOsc(v);
		oPhase[o] = startPhase(o, offset);
		oPhase[o + 1.0] = 0.0;
		oPhase[o + 2.0] = 0.0;
		oscBase(o, note);
		oscBase(o + 1.0, note);
		oscBase(o + 2.0, note);
		if(v == 5.0) {
			if(isOpen != 0.0) aeDecay[5.0] = hhDecOpen;
			else aeDecay[5.0] = hhDecClosed;
		}
		aeTrigger(v);
		velo[v] = fr(vel / 127.0);
		trPhase[v] = 0.0;
		snap[v] = 1.0;
		updatePan(v);
	}

	void voiceTrigger(double slot, double vel, double note) {
		if(slot < 3.0) drumTrigger(slot, vel, note);
		else if(slot == 3.0) snareTrigger(vel, note);
		else if(slot == 4.0) metalTrigger(4.0, vel, 0.0, note);
		else metalTrigger(5.0, vel, slot - 5.0, note);
	}

	void queueTrig(double slot, double code) {
		if(code <= 0.0) return;
		tPend[slot] = 1.0;
		tVel[slot] = code - 128.0 * std::floor(code / 128.0);
		double n = std::floor(code / 128.0);
		tNote[slot] = n - 128.0 * std::floor(n / 128.0);
	}

	void drumAsync(double v) {
		double o = 2.0 * v;
		double eg = decayCalc(v);
		oPitch[o] = fr(1.0 + fr(eg * pAmt[v]));
		if(trWave[v] == 0.0) oPitch[o] = fr(oPitch[o] + fr(snapCalc(v, trPitch[v]) * trVol[v]));
		oFm[o] = fr(fmAmt[v] * eg);
		if(aeAttack[v] == 1.0 && (aeState[v] == EG_A || aeState[v] == EG_REPEAT)) {
			ampIn[v] = aeCalc(v);
			lastGain[v] = ampIn[v];
		} else {
			lastGain[v] = ampIn[v];
			ampIn[v] = aeCalc(v);
		}
		oscSetFreq(o);
		oscSetFreq(o + 1.0);
	}

	void drumSync(double v) {
		double o = 2.0 * v;
		oscBlock(o + 1.0, 64.0, fmAmt[v], pwm[v]);
		if(mixOscs[v] != 0.0) {
			oscBlock(o, 0.0, fr(1.0 - fmAmt[v]), pwm[v]);
			qaddBuf(0.0, 64.0);
		} else {
			oscFmBlock(o, 64.0, 0.0, 1.0, pwm[v]);
		}
		transBlock(v, 64.0);
		qaddBuf(0.0, 64.0);
		svfBlock(v, 0.0);
		
		double g1 = fr(ampIn[v]);
		double g0 = fr(lastGain[v]);
		double dg = fr(g1 - g0);
		for(double i = 0.0; i < N; i++) SCR[i] = i16(SCR[i] * (g0 + fr(i / 63.0) * dg));
		if(volMod[v] != 0.0) {
			for(double i = 0.0; i < N; i++) SCR[i] = i16(fr(SCR[i] * velo[v]));
		}
		
		for(double i = 0.0; i < N; i++) {
			driveB[v] = fr(driveB[v] + 0.009999999776482582 * fr(dShape[v] - driveB[v]));
			SCR[i] = shapeSample(SCR[i], driveB[v]);
		}
		for(double i = 0.0; i < N; i++) {
			mixVolB[v] = fr(mixVolB[v] + 0.009999999776482582 * fr(vol[v] - mixVolB[v]));
			fader[v] = fr(fader[v] + 0.009999999776482582 * fr(1.0 - fader[v]));
			SCR[i] = i16(fr(SCR[i] * fr(mixVolB[v] * fader[v])));
		}
	}

	void snareAsync() {
		double eg = decayCalc(3.0);
		oPitch[6.0] = fr(1.0 + fr(eg * pAmt[3.0]));
		egVol[3.0] = fr(aeCalc(3.0));
		if(trWave[3.0] == 0.0) oPitch[6.0] = fr(oPitch[6.0] + fr(snapCalc(3.0, trPitch[3.0]) * trVol[3.0]));
		oscSetFreq(6.0);
		oscSetFreq(7.0);
	}

	void snareSync() {
		noiseBlock(7.0, 0.0, 0.8999999761581421);
		svfBlock(3.0, 0.0);
		oscBlock(6.0, 64.0, fr(1.0 - snMix), pwm[3.0]);
		transBlock(3.0, 128.0);
		double cv = fr(vol[3.0] * egVol[3.0]);
		if(volMod[3.0] != 0.0) cv = fr(fr(vol[3.0] * velo[3.0]) * egVol[3.0]);
		for(double j = 0.0; j < N; j++) {
			double tmp = fr(fr(SCR[j] * snMix + SCR[64.0 + j]) + SCR[128.0 + j]);
			fader[3.0] = fr(fader[3.0] + 0.10000000149011612 * fr(1.0 - fader[3.0]));
			SCR[j] = i16(fr(fr(cv * tmp) * fader[3.0]));
		}
		distBlock(3.0, 0.0);
	}

	void metalAsync(double v) {
		double o = mainOsc(v);
		egVol[v] = fr(aeCalc(v));
		if(trWave[v] == 0.0) oPitch[o] = fr(1.0 + fr(snapCalc(v, trPitch[v]) * trVol[v]));
		oscSetFreq(o);
		oscSetFreq(o + 1.0);
		oscSetFreq(o + 2.0);
	}

	void metalSync(double v) {
		double o = mainOsc(v);
		oscBlock(o + 1.0, 64.0, fmA1[v], pwm[v]);
		oscBlock(o + 2.0, 128.0, fmA2[v], pwm[v]);
		qaddBuf(64.0, 128.0);
		double gain = 1.0;
		if(v == 5.0) gain = 0.5;
		oscFmBlock(o, 64.0, 0.0, gain, pwm[v]);
		svfBlock(v, 0.0);
		transBlock(v, 64.0);
		double cv = fr(vol[v] * egVol[v]);
		if(volMod[v] != 0.0) cv = fr(fr(vol[v] * velo[v]) * egVol[v]);
		qaddBuf(0.0, 64.0);
		for(double j = 0.0; j < N; j++) {
			fader[v] = fr(fader[v] + 0.10000000149011612 * fr(1.0 - fader[v]));
			SCR[j] = i16(fr(SCR[j] * fr(cv * fader[v])));
		}
		distBlock(v, 0.0);
	}

	void compSetRatio(double r) {
		if(r == 1.0) cRatio = 0.5;
		else if(r == 2.0) cRatio = 1.0 / 3.0;
		else if(r == 3.0) cRatio = 0.25;
		else if(r == 4.0) cRatio = 1.0 / 6.0;
		else if(r == 5.0) cRatio = 0.125;
		else cRatio = 1.0;
	}

	void fxUpdate() {
		if(fxType == 1.0) {
			dsDrive = fxP[0.0];
			dsP1 = fxP[1.0];
			dsP2 = fxP[2.0];
			dsP3 = fxP[3.0];
		} else if(fxType == 2.0) {
			oFreq[14.0] = fr(fxP[0.0] * 880.0);
			oscSetFreq(14.0);
		} else if(fxType == 3.0) {
			
			cAttack = fr(std::exp(-1000.0 / fr(fr(0.029999999329447746 + fr(fxP[0.0] * 100.0)) * fsr)));
			cRelease = fr(std::exp(-1000.0 / fr(fr(25.0 + fr(fxP[1.0] * 175.0)) * fsr)));
			cTresh = fr(-96.0 + fr(fxP[2.0] * 96.0));
			cMarkup = fr(1.0 + fxP[3.0] * 2.0);
		} else if(fxType == 4.0) {
			dlRange = fxP[1.0];
			delaySetTime(dlTime);
			delaySetTime(fxP[0.0]);
			dlToneR = fr(fxP[2.0] * fxP[2.0]);
			dlFb = fxP[3.0];
		}
	}

	double fxDryWetMix(double dry, double wet) {
		return wrap16(dry + ssat(fr((wet - dry) * fxDryWet)));
		return 0.0;
	}

	double ecc83(double x) {
		double inp = std::trunc(x);
		double s = sat16(inp);
		double itg = std::floor(s / 512.0) + 64.0;
		double frac = (inp - 512.0 * std::floor(inp / 512.0)) / 512.0;
		return ECC83[itg] + (ECC83[itg + 1.0] - ECC83[itg]) * frac;
		return 0.0;
	}

	double foldback(double x) {
		x = fr(x);
		if(x > 1.0 || x < -1.0) {
			double a = fr(x - 1.0);
			x = fr(std::fabs(std::fabs(a - 4.0 * std::trunc(a / 4.0)) - 2.0) - 1.0);
		}
		return x;
		return 0.0;
	}

	double diode(double x) {
		x = fr(x);
		if(x < -1.0) x = -1.0;
		if(x > 1.0) x = 1.0;
		double index = fr(fr(x + 1.0) * 128.0);
		double itg = std::trunc(index);
		if(itg >= 256.0) return DIODE[256.0];
		double t = fr(index - itg);
		double a = DIODE[itg];
		return fr(t * DIODE[itg + 1.0] + fr(a - fr(t * a)));
		return 0.0;
	}

	double rat(double c, double x, double gain, double coff) {
		double s = x / 32768.0 + dsLast[c] * dsP1 * 0.125;
		dsHp1[c] = dsHp1[c] + 0.64116641920131193922 * (s - dsHp1[c]);
		s = s - dsHp1[c];
		dsLp1[c] = dsLp1[c] + (1.0 - 0.1025353241628911807) * (s - dsLp1[c]);
		s = dsLp1[c];
		dsHp3[c] = dsHp3[c] + (1.0 - 0.99149556438154282898) * (s - dsHp3[c]);
		s = s - dsHp3[c];
		dsLp2[c] = dsLp2[c] + (1.0 - 0.93130041642945205043) * (s - dsLp2[c]);
		s = dsLp2[c] * gain;
		double diff = s - dsSlew[c];
		if(std::fabs(diff) > 6.79655641141821477118) {
			if(diff > 0.0) diff = 6.79655641141821477118;
			else diff = -6.79655641141821477118;
		}
		dsSlew[c] = dsSlew[c] + diff;
		if(dsSlew[c] > 4.2) dsSlew[c] = 4.2;
		else if(dsSlew[c] < -4.2) dsSlew[c] = -4.2;
		dsLp3[c] = dsLp3[c] + coff * (diode(dsSlew[c]) - dsLp3[c]);
		dsLast[c] = dsLp3[c] * dsP3;
		return ssat(dsLast[c] * 32768.0);
		return 0.0;
	}

	double delayTimeSamples(double cv) {
		double lowMin = fr(0.0006 * fsr);
		double lowMax = fr(0.02 * fsr);
		double lo = flerp(lowMin, lowMax, dlRange);
		double hiMax = 32767.0;
		if(dlType != 0.0) hiMax = fr(32767.0 * 0.47999998927116394);
		double hi = flerp(lowMax, hiMax, dlRange);
		return flerp(lo, hi, cv);
		return 0.0;
	}

	double flerp(double a, double b, double x) {
		return fr(fr(a * fr(1.0 - x)) + fr(b * x));
		return 0.0;
	}

	void delaySetTime(double t) {
		if(dlInterp <= 0.0) {
			dlTime = t;
			double offset = delayTimeSamples(fr(dlTime * dlRange));
			double offItg = std::trunc(offset);
			dlFracNew = fr(offset - offItg);
			double mask = 32768.0;
			if(dlType != 0.0) mask = 16384.0;
			double r = dlWrite - 1.0 - offItg;
			dlNew = r - mask * std::floor(r / mask);
			dlInterp = 1.0;
			dlStep = fr(1.0 / fr(fsr * 0.009999999776482582));
		} else {
			dlPendTime = t;
			dlPending = 1.0;
		}
	}

	double dlRead(double pos, double frac, double region) {
		double mask = 32768.0;
		if(dlType != 0.0) mask = 16384.0;
		double p2 = pos + 1.0;
		p2 = p2 - mask * std::floor(p2 / mask);
		return i16(fr(flerp(dlAt(region + pos), dlAt(region + p2), frac) * 32767.0));
		return 0.0;
	}

	double dlAt(double i) {
		if(i < 0.0 || i >= 32768.0) return 0.0;
		return DLB[i];
		return 0.0;
	}

	double dlAdvance(double pos) {
		double mask = 32768.0;
		if(dlType != 0.0) mask = 16384.0;
		pos = pos + 1.0;
		return pos - mask * std::floor(pos / mask);
		return 0.0;
	}

	void fxProcess() {
		double ca = 128.0;
		double cb = 192.0;
		double stereo = 1.0;
		double r = fxRouting;
		if(r == 1.0) {
			ca = 0.0;
			cb = 64.0;
		} else if(r == 2.0) {
			stereo = 0.0;
		} else if(r == 3.0) {
			stereo = 0.0;
			ca = 192.0;
		} else if(r == 4.0) {
			stereo = 0.0;
			ca = 0.0;
		} else if(r == 5.0) {
			stereo = 0.0;
			ca = 64.0;
		}
		double t = fxType;
		if(t == 1.0) {
			double coff = 0.06537948995454451662 + dsP2 * 0.92410701734426630737;
			if(dsType == 0.0) {
				double om = fr((1.0 + 0.55 * dsP1) + 0.55 * dsP1);
				double dr = fr(1.0 + dsDrive * 4.0);
				if(stereo == 0.0) dr = fr(1.0 + dsDrive);
				for(double i = 0.0; i < N; i++) {
					double l = FXB[2.0 * i];
					double rr = FXB[2.0 * i + 1.0];
					dsLp3[0.0] = dsLp3[0.0] + coff * (ecc83(fr(l * dr)) - dsLp3[0.0]);
					double wl = ssat(dsLp3[0.0] * om * dsP3 * 32768.0);
					if(stereo != 0.0) {
						dsLp3[1.0] = dsLp3[1.0] + coff * (ecc83(fr(rr * dr)) - dsLp3[1.0]);
						double wr = ssat(dsLp3[1.0] * om * dsP3 * 32768.0);
						OUTB[cb + i] = sat16(OUTB[cb + i] + fxDryWetMix(rr, wr));
					}
					OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, wl));
				}
			} else if(dsType == 1.0) {
				double dr = fr(1.0 + dsDrive * 4.0);
				for(double i = 0.0; i < N; i++) {
					double l = FXB[2.0 * i];
					double rr = FXB[2.0 * i + 1.0];
					dsLp3[0.0] = dsLp3[0.0] + coff * (fr(fr((l / 32768.0) * dr) + dsP1) - dsLp3[0.0]);
					double wl = ssat(fr(fr(foldback(dsLp3[0.0]) * dsP3) * 32768.0));
					if(stereo != 0.0) {
						dsLp3[1.0] = dsLp3[1.0] + coff * (fr(fr((rr / 32768.0) * dr) + dsP1) - dsLp3[1.0]);
						double wr = ssat(fr(fr(foldback(dsLp3[1.0]) * dsP3) * 32768.0));
						OUTB[cb + i] = sat16(OUTB[cb + i] + fxDryWetMix(rr, wr));
					}
					OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, wl));
				}
			} else {
				double gain = 1.0 + fr(dsDrive * 2304.0);
				for(double i = 0.0; i < N; i++) {
					double l = FXB[2.0 * i];
					double rr = FXB[2.0 * i + 1.0];
					double wl = rat(0.0, l, gain, coff);
					if(stereo != 0.0) {
						double wr = rat(1.0, rr, gain, coff);
						OUTB[cb + i] = sat16(OUTB[cb + i] + fxDryWetMix(rr, wr));
					}
					OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, wl));
				}
			}
		} else if(t == 2.0) {
			oscBlock(14.0, 320.0, 1.0, 0.3);
			for(double i = 0.0; i < N; i++) {
				double l = FXB[2.0 * i];
				double rr = FXB[2.0 * i + 1.0];
				double m = SCR[320.0 + i];
				if(stereo != 0.0) {
					OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, std::floor(l * m / 65536.0)));
					OUTB[cb + i] = sat16(OUTB[cb + i] + fxDryWetMix(rr, std::floor(rr * m / 65536.0)));
				} else {
					double wet = sat16(OUTB[ca + i] + std::floor(l * m / 65536.0));
					OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, wet));
				}
			}
		} else if(t == 3.0) {
			for(double i = 0.0; i < N; i++) {
				double l = FXB[2.0 * i];
				double rr = FXB[2.0 * i + 1.0];
				double x = l / 32768.0;
				if(stereo != 0.0) x = fr(0.5 * (l / 32768.0) + 0.5 * (rr / 32768.0));
				double peakdB = fr(std::log(fr(std::fabs(x) + 1.0E-25))) * 8.6858896380650365530225783783321;
				double over = peakdB - cTresh;
				if(over < 0.0) over = 0.0;
				double coeff = cRelease;
				if(over > cEnv) coeff = cAttack;
				cEnv = over + coeff * (cEnv - over);
				double gr = fr(std::exp(fr(cEnv * (cRatio - 1.0) * 0.11512925464970228420089957273422)));
				if(stereo != 0.0) {
					OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, ssat(l * gr * cMarkup)));
					OUTB[cb + i] = sat16(OUTB[cb + i] + fxDryWetMix(rr, ssat(rr * gr * cMarkup)));
				} else {
					OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, i16(l * gr * cMarkup)));
				}
			}
		} else if(t == 4.0) {
			if(dlType == 0.0) delayNormal(ca, cb, stereo);
			else delayPingPong(ca, cb, stereo);
		} else {
			for(double i = 0.0; i < N; i++) {
				OUTB[ca + i] = sat16(OUTB[ca + i] + FXB[2.0 * i]);
				if(stereo != 0.0) OUTB[cb + i] = sat16(OUTB[cb + i] + FXB[2.0 * i + 1.0]);
			}
		}
	}

	void delayNormal(double ca, double cb, double stereo) {
		for(double i = 0.0; i < N; i++) {
			double l = FXB[2.0 * i];
			double rr = FXB[2.0 * i + 1.0];
			double smp = 0.0;
			if(dlInterp <= 0.0) {
				dlT0 = dlRead(dlOld, dlFracOld, 0.0);
				dlOld = dlAdvance(dlOld);
				smp = dlT0;
				if(dlPending != 0.0) {
					dlPending = 0.0;
					delaySetTime(dlPendTime);
				}
			} else {
				dlT0 = dlRead(dlOld, dlFracOld, 0.0);
				dlOld = dlAdvance(dlOld);
				dlT1 = dlRead(dlNew, dlFracNew, 0.0);
				dlNew = dlAdvance(dlNew);
				smp = i16(fr(dlT0 * dlInterp) + dlT1 * (1.0 - dlInterp));
				dlInterp = fr(dlInterp - dlStep);
				if(dlInterp <= 0.0) {
					dlOld = dlNew;
					dlFracOld = dlFracNew;
				}
			}
			dlToneB = fr(dlToneB + dlToneR * fr(smp - dlToneB));
			smp = i16(dlToneB);
			double itg = sat16(sat16(l + rr) + i16(fr(smp * dlFb)));
			DLB[dlWrite] = f16(cbx::min(1.0, cbx::max(-1.0, fr(itg / 32767.0))));
			dlWrite = dlAdvance(dlWrite);
			OUTB[ca + i] = sat16(OUTB[ca + i] + sat16(l + ssat(fr((smp - l) * fxDryWet))));
			if(stereo != 0.0) OUTB[cb + i] = sat16(OUTB[cb + i] + sat16(rr + ssat(fr((smp - rr) * fxDryWet))));
		}
	}

	void delayPingPong(double ca, double cb, double stereo) {
		for(double i = 0.0; i < N; i++) {
			double l = FXB[2.0 * i];
			double rr = FXB[2.0 * i + 1.0];
			double outL = 0.0;
			double outR = 0.0;
			if(dlInterp <= 0.0) {
				dlT0 = dlRead(dlOld, dlFracOld, 0.0);
				dlU0 = dlRead(dlOld, dlFracOld, 16383.0);
				dlOld = dlAdvance(dlOld);
				outL = dlT0;
				outR = dlU0;
				if(dlPending != 0.0) {
					dlPending = 0.0;
					delaySetTime(dlPendTime);
				}
			} else {
				dlT0 = dlRead(dlOld, dlFracOld, 0.0);
				dlU0 = dlRead(dlOld, dlFracOld, 16383.0);
				dlOld = dlAdvance(dlOld);
				dlT1 = dlRead(dlNew, dlFracNew, 0.0);
				dlU1 = dlRead(dlNew, dlFracNew, 16383.0);
				dlNew = dlAdvance(dlNew);
				outL = i16(fr(dlT0 * dlInterp) + dlT1 * (1.0 - dlInterp));
				outR = i16(fr(dlU0 * dlInterp) + dlU1 * (1.0 - dlInterp));
				dlInterp = fr(dlInterp - dlStep);
				if(dlInterp <= 0.0) {
					dlOld = dlNew;
					dlFracOld = dlFracNew;
				}
			}
			dlToneB = fr(dlToneB + dlToneR * fr(outL - dlToneB));
			outL = i16(dlToneB);
			dlTone2B = fr(dlTone2B + dlToneR * fr(outR - dlTone2B));
			outR = i16(dlTone2B);
			if(dlWrite < 16385.0) DLB[16383.0 + dlWrite] = f16(cbx::min(1.0, cbx::max(-1.0, fr(sat16(l + i16(fr(outL * dlFb))) / 32767.0))));
			DLB[dlWrite] = f16(cbx::min(1.0, cbx::max(-1.0, fr(sat16(rr + i16(fr(outR * dlFb))) / 32767.0))));
			dlWrite = dlAdvance(dlWrite);
			OUTB[ca + i] = sat16(OUTB[ca + i] + sat16(l + ssat(fr((outL - l) * fxDryWet))));
			if(stereo != 0.0) OUTB[cb + i] = sat16(OUTB[cb + i] + sat16(rr + ssat(fr((outR - rr) * fxDryWet))));
		}
	}

	void renderBlock() {
		scanParams();
		autoScan();
		for(double s = 0.0; s < 7.0; s++) {
			if(tPend[s] != 0.0) {
				tPend[s] = 0.0;
				voiceTrigger(s, tVel[s], tNote[s]);
				tCount[s] = tCount[s] + 1.0;
			}
		}
		resetTargets();
		for(double i = 0.0; i < 6.0; i++) modUpdate(vmDest[i], vmAmount[i], vmLast[i]);
		for(double l = 0.0; l < 6.0; l++) modUpdate(lDest[l], lAmount[l], lfoCalc(l));
		for(double v = 0.0; v < 6.0; v++) svfRecalc(v);
		drumAsync(0.0);
		drumAsync(1.0);
		drumAsync(2.0);
		snareAsync();
		metalAsync(4.0);
		metalAsync(5.0);
		for(double i = 0.0; i < 256.0; i++) OUTB[i] = 0.0;
		for(double i = 0.0; i < 128.0; i++) FXB[i] = 0.0;
		for(double v = 0.0; v < 3.0; v++) {
			drumSync(v);
			srReduce(v, 0.0);
			mixAdd(v, 0.0);
		}
		snareSync();
		srReduce(3.0, 0.0);
		mixAdd(3.0, 0.0);
		metalSync(4.0);
		srReduce(4.0, 0.0);
		mixAdd(4.0, 0.0);
		metalSync(5.0);
		srReduce(5.0, 0.0);
		mixAdd(5.0, 0.0);
		fxProcess();
	}

	double autoPar(double code) {
		if(code <= 127.0) return code - 1.0;
		return code;
		return 0.0;
	}

	void autoSet(double code, double val) {
		double par = autoPar(code);
		if(par < 0.0 || par >= END_OF_SOUND_PARAMETERS) return;
		double v = val;
		if(v < 0.0) v = O[par];
		if(v < 0.0) return;
		setLxrParam(par, v);
	}

	void autoApply(double t, double value) {
		double w = value - 4294967296.0 * std::floor(value / 4294967296.0);
		double d1 = w - 256.0 * std::floor(w / 256.0);
		double v1 = std::floor(w / 256.0) - 256.0 * std::floor(w / 65536.0);
		double d2 = std::floor(w / 65536.0) - 256.0 * std::floor(w / 16777216.0);
		double v2 = std::floor(w / 16777216.0) - 256.0 * std::floor(w / 4294967296.0);
		for(double k = 0.0; k < 2.0; k++) {
			double n = 2.0 * t + k;
			if(autoDest[n] != 255.0) autoSet(autoDest[n], -1.0);
			if(k == 0.0) autoDest[n] = d1;
			else autoDest[n] = d2;
		}
		if(autoDest[2.0 * t] != 255.0) autoSet(autoDest[2.0 * t], v1);
		if(autoDest[2.0 * t + 1.0] != 255.0) autoSet(autoDest[2.0 * t + 1.0], v2);
	}

	void autoScan() {
		for(double t = 0.0; t < 7.0; t++) {
			double v = autoValue(t);
			if(v != autoLast[t]) {
				autoLast[t] = v;
				if(v > 0.0) autoApply(t, v);
			}
		}
	}

	double autoValue(double t) {
		if(t == 0.0) return auto_d1;
		if(t == 1.0) return auto_d2;
		if(t == 2.0) return auto_d3;
		if(t == 3.0) return auto_sn;
		if(t == 4.0) return auto_cy;
		if(t == 5.0) return auto_ch;
		return auto_oh;
		return 0.0;
	}

	void engineInit() {
		for(double o = 0.0; o < 16.0; o++) {
			oFreq[o] = 440.0;
			oPitch[o] = 1.0;
			oWave[o] = 1.0;
			oCoarse[o] = 70.0;
			oFine[o] = 64.0;
		}
		for(double v = 0.0; v < 3.0; v++) {
			oWave[2.0 * v] = 1.0 + v;
			oPitch[2.0 * v] = 0.0;
			fmAmt[v] = 0.5;
			mixOscs[v] = 1.0;
			fType[v] = F_LP;
		}
		oWave[9.0] = W_SINE;
		oWave[10.0] = W_NOISE;
		oWave[12.0] = W_SINE;
		oWave[13.0] = W_NOISE;
		oFm[8.0] = 1.0;
		oFm[11.0] = 1.0;
		oFreq[14.0] = 100.0;
		oWave[14.0] = 3.0;
		oscSetFreq(14.0);
		for(double v = 0.0; v < 6.0; v++) {
			vol[v] = 0.8;
			volMod[v] = 1.0;
			pAmt[v] = 0.5;
			dShape[v] = 2.0 * (-0.0078125) / (1.0 + 0.0078125);
			trPitch[v] = 1.0;
			trVol[v] = 1.0;
			aeAttack[v] = 0.01;
			aeDecay[v] = 0.01;
			
			double a = -0.5 * 1.999;
			aeSlope[v] = 2.0 * a / (1.0 - a);
			aeInv[v] = -2.0 * a / (1.0 + a);
			peDecay[v] = 0.01;
			svF[v] = 0.1125;
			svQ[v] = 0.9;
			svDrive[v] = 0.315;
			lInc[v] = 1.0;
			lFreq[v] = 1.0;
			fmA1[v] = 0.5;
			fmA2[v] = 0.5;
			decRate[v] = 1.0;
		}
		decRate[6.0] = 1.0;
		for(double k = 0.0; k < 24.0; k++) rngS[k] = wrap32(625341585.0 + k * 2654435769.0);
		for(double i = 0.0; i < 256.0; i++) {
			P[i] = -1.0;
			O[i] = -1.0;
		}
		for(double n = 0.0; n < 14.0; n++) autoDest[n] = 255.0;
	}

	void dspsetup() {
		fsr = samplerate();
		kr = FS_REF / fsr;
		if(booted == 0.0) {
			tablesInit();
			engineInit();
			booted = 1.0;
		}
		
		for(double i = 0.0; i < 256.0; i++) O[i] = -1.0;
		blockPos = N;
	}

