	double pint(double x, double hi) {
		double v = std::floor(x + 0.5);
		if(v < 0.0) return 0.0;
		if(v > hi) return hi;
		return v;
		return 0.0;
	}

	void fillSine(double base, const List& c) {
		for(double i = 0.0; i < c.length(); i++) {
			double n = c[i];
			for(double k = 0.0; k < 3.0; k++) {
				double idx = base * 3.0 + i * 3.0 + k;
				double u = n - 65536.0 * std::floor(n / 65536.0);
				n = std::floor(n / 65536.0);
				if(idx < 4097.0) SINE[idx] = u - 32768.0;
			}
		}
	}

	void fillWave(double base, const List& c) {
		for(double i = 0.0; i < c.length(); i++) {
			double n = c[i];
			for(double k = 0.0; k < 3.0; k++) {
				double idx = base * 3.0 + i * 3.0 + k;
				double u = n - 65536.0 * std::floor(n / 65536.0);
				n = std::floor(n / 65536.0);
				if(idx < 33795.0) WT[idx] = u - 32768.0;
			}
		}
	}

	void fillTransient(double base, const List& c) {
		for(double i = 0.0; i < c.length(); i++) {
			double n = c[i];
			for(double k = 0.0; k < 6.0; k++) {
				double idx = base * 6.0 + i * 6.0 + k;
				double u = n - 256.0 * std::floor(n / 256.0);
				n = std::floor(n / 256.0);
				if(idx < 26460.0) TR[idx] = u - 128.0;
			}
		}
	}

	void fillList(double which, const List& c) {
		for(double i = 0.0; i < c.length(); i++) {
			if(which == 0.0) ECC83[i] = c[i];
			else if(which == 1.0) DIODE[i] = c[i];
			else if(which == 2.0) NOTEF[i] = c[i];
			else if(which == 3.0) MT[i] = c[i];
			else HASPTR[c[i]] = 1.0;
		}
	}

